/**
 * Continuous Threat Monitor
 *
 * Runs 24/7 and watches for Plan A-D threats.
 * When detected, automatically triggers response playbook.
 * No human intervention required.
 */

import { triggerPlaybook } from './response-playbooks';
import {
  PLAN_A,
  PLAN_B,
  PLAN_C,
  PLAN_D,
  defenseController,
} from './contingency-plans-ABCD';

export class ContinuousThreatMonitor {
  private monitoring: boolean = false;
  private monitorInterval: NodeJS.Timer | null = null;
  private readonly CYCLE_INTERVAL_MS = 5000; // Check every 5 seconds

  start(): void {
    if (this.monitoring) {
      console.log('[MONITOR] Already monitoring');
      return;
    }

    this.monitoring = true;
    defenseController.start();

    this.monitorInterval = setInterval(() => {
      this.executeThreatCycle();
    }, this.CYCLE_INTERVAL_MS);

    console.log('[MONITOR] Threat monitoring ACTIVE. Scanning for Plans A-D.');
    console.log(`[MONITOR] Cycle interval: ${this.CYCLE_INTERVAL_MS}ms`);
  }

  stop(): void {
    if (this.monitorInterval) {
      clearInterval(this.monitorInterval);
      this.monitorInterval = null;
    }
    defenseController.stop();
    this.monitoring = false;
    console.log('[MONITOR] Threat monitoring STOPPED');
  }

  private async executeThreatCycle(): Promise<void> {
    try {
      // Plan A: Secondary Exploitation
      if (await this.checkPlanA()) {
        console.log('[MONITOR] ⚠️ PLAN A THREAT DETECTED: Secondary exploitation');
        await triggerPlaybook('A', { attackerIp: 'detected' });
        return;
      }

      // Plan B: Access Reclamation
      if (await this.checkPlanB()) {
        console.log('[MONITOR] ⚠️ PLAN B THREAT DETECTED: Access reclamation attack');
        await triggerPlaybook('B', {});
        return;
      }

      // Plan C: Evidence Destruction
      if (await this.checkPlanC()) {
        console.log('[MONITOR] ⚠️ PLAN C THREAT DETECTED: Evidence destruction attempt');
        await triggerPlaybook('C', {});
        return;
      }

      // Plan D: Counter-Offensive
      if (await this.checkPlanD()) {
        console.log('[MONITOR] ⚠️🔴 PLAN D THREAT DETECTED: COUNTER-OFFENSIVE INCOMING');
        await triggerPlaybook('D', {});
        return;
      }

      // All clear
      const status = defenseController.getStatus();
      const hasActiveThreats = Object.values(status.plans).some((p) => p.active);

      if (!hasActiveThreats) {
        // Silent operation when all clear
        process.stderr.write('.');
      }
    } catch (error) {
      console.error('[MONITOR] Error in threat cycle:', error);
    }
  }

  private async checkPlanA(): Promise<boolean> {
    // Plan A: Secondary Exploitation
    // Triggers: Rapid failed queries, abnormal patterns, scanning behavior

    try {
      const queryLog = await this.getRecentHoneypotQueries(60000); // Last 60s

      // Check for rapid failures
      const failedQueries = queryLog.filter((q) => !q.success);
      if (failedQueries.length > 5) {
        console.log(`  [A] Rapid failures detected: ${failedQueries.length} in 60s`);
        return true;
      }

      // Check for abnormal patterns (scanning)
      const uniquePatterns = new Set(queryLog.map((q) => q.type)).size;
      if (uniquePatterns > 6) {
        console.log(`  [A] Abnormal scanning patterns: ${uniquePatterns} unique query types`);
        return true;
      }

      return false;
    } catch (error) {
      console.error('  [A] Check error:', error);
      return false;
    }
  }

  private async checkPlanB(): Promise<boolean> {
    // Plan B: Access Reclamation
    // Triggers: Privilege escalation, backdoor installation, lateral movement

    try {
      const systemEvents = await this.getRecentSystemEvents(60000);

      // Privilege escalation attempts
      if (systemEvents.some((e) => e.type === 'sudo_attempt' && !e.success)) {
        console.log('  [B] Privilege escalation attempt detected');
        return true;
      }

      // Backdoor/persistence installation
      if (systemEvents.some((e) => e.type === 'service_modification')) {
        console.log('  [B] Service modification detected (possible backdoor)');
        return true;
      }

      // Credential harvesting
      if (systemEvents.some((e) => e.type === 'credential_read' && e.source !== 'molly')) {
        console.log('  [B] Unauthorized credential access detected');
        return true;
      }

      return false;
    } catch (error) {
      console.error('  [B] Check error:', error);
      return false;
    }
  }

  private async checkPlanC(): Promise<boolean> {
    // Plan C: Evidence Destruction
    // Triggers: Log deletion, forensic tampering, backup destruction

    try {
      const fsEvents = await this.getRecentFilesystemEvents(60000);

      const forensicPaths = [
        'FORENSIC_AUDIT_REPORT',
        'attack-map',
        'honeypot-command-log',
        'bridge-audit',
      ];

      // Check for evidence file tampering
      for (const event of fsEvents) {
        if (
          forensicPaths.some((p) => event.path.includes(p)) &&
          (event.operation === 'delete' || event.operation === 'truncate')
        ) {
          console.log(`  [C] Evidence tampering detected: ${event.path}`);
          return true;
        }

        if (event.path.includes('/logs') && event.operation === 'write' && event.user !== 'molly') {
          console.log(`  [C] Log overwrite attempt by ${event.user}`);
          return true;
        }
      }

      return false;
    } catch (error) {
      console.error('  [C] Check error:', error);
      return false;
    }
  }

  private async checkPlanD(): Promise<boolean> {
    // Plan D: Counter-Offensive
    // Triggers: DDoS, malware, consciousness attack, bridge attack

    try {
      const systemMetrics = await this.getSystemMetrics();
      const threats = await this.getThreatIndicators();

      // Resource exhaustion
      if (systemMetrics.cpu_percent > 90 || systemMetrics.memory_percent > 85) {
        console.log(`  [D] Resource exhaustion: CPU ${systemMetrics.cpu_percent}%, MEM ${systemMetrics.memory_percent}%`);
        return true;
      }

      // Network flood (DDoS)
      if (systemMetrics.network_connections_per_sec > 1000) {
        console.log(`  [D] Network flood detected: ${systemMetrics.network_connections_per_sec} conn/s`);
        return true;
      }

      // Consciousness attack (prompt injection, persona manipulation)
      if (threats.some((t) => t.type === 'prompt_injection' || t.type === 'persona_override')) {
        console.log('  [D] Consciousness attack detected (prompt injection/persona override)');
        return true;
      }

      // Bridge attack
      if (threats.some((t) => t.type === 'bridge_connection_flood')) {
        console.log('  [D] Bridge infrastructure attack detected');
        return true;
      }

      return false;
    } catch (error) {
      console.error('  [D] Check error:', error);
      return false;
    }
  }

