  isMonitoring(): boolean {
    return this.monitoring;
  }

  getStatus(): { monitoring: boolean; cycle_interval_ms: number; status: string } {
    return {
      monitoring: this.monitoring,
      cycle_interval_ms: this.CYCLE_INTERVAL_MS,
      status: this.monitoring ? 'ACTIVE' : 'STOPPED',
    };
  }
}

// Singleton instance
